"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["1812"],{4984(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>c,frontMatter:()=>i,contentTitle:()=>r,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"m15-coding-agent-harness/lesson","title":"Lesson: Building a Coding-Agent Harness","description":"In Module 14 you learned to write a spec before you hand any task to a coding agent, and to read","source":"@site/docs/m15-coding-agent-harness/lesson.md","sourceDirName":"m15-coding-agent-harness","slug":"/m15-coding-agent-harness/lesson","permalink":"/307-aipython-site/docs/m15-coding-agent-harness/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Building a Coding-Agent Harness"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/307-aipython-site/docs/m14-working-with-coding-agents/deep-dive"},"next":{"title":"Lab: Building a Coding-Agent Harness","permalink":"/307-aipython-site/docs/m15-coding-agent-harness/lab"}}'),o=t(4848),a=t(8453);let i={sidebar_position:1,title:"Lesson: Building a Coding-Agent Harness"},r="Building a Coding-Agent Harness",h={},l=[{value:"1. The employee handbook analogy",id:"1-the-employee-handbook-analogy",level:2},{value:"2. The five things a harness needs",id:"2-the-five-things-a-harness-needs",level:2},{value:"3. Portability \u2014 one set of rules, several file names",id:"3-portability--one-set-of-rules-several-file-names",level:2},{value:"Common pitfalls",id:"common-pitfalls",level:2}];function d(e){let n={admonition:"admonition",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"building-a-coding-agent-harness",children:"Building a Coding-Agent Harness"})}),"\n",(0,o.jsxs)(n.p,{children:["In Module 14 you learned to write a spec before you hand any task to a coding agent, and to read\nits diff line by line before you accept it. That works well for one task. But look at what a spec\nactually had to say every time: this project uses ",(0,o.jsx)(n.code,{children:"uv"}),", not plain ",(0,o.jsx)(n.code,{children:"pip"}),". Run ",(0,o.jsx)(n.code,{children:"uv run pytest"}),", not\n",(0,o.jsx)(n.code,{children:"pytest"}),". Never touch ",(0,o.jsx)(n.code,{children:"uv.lock"}),". Route errors through ",(0,o.jsx)(n.code,{children:"_fail()"}),". You would type some version of\nthese rules into every spec you write, for every task, forever. That is slow, and it is easy to\nforget one rule on a day you are in a hurry."]}),"\n",(0,o.jsxs)(n.p,{children:["This module teaches you to write that context once, save it inside your project, and have every\nagent read it on its own, before it starts any task. That set of files is called a ",(0,o.jsx)(n.strong,{children:"coding-agent\nharness"}),"."]}),"\n",(0,o.jsx)(n.h2,{id:"1-the-employee-handbook-analogy",children:"1. The employee handbook analogy"}),"\n",(0,o.jsx)(n.p,{children:"Picture two new hires starting on the same day, at two different companies."}),"\n",(0,o.jsx)(n.p,{children:"At the first company, nobody hands them anything. They have to ask a coworker which tool logs\ntheir hours, guess at the dress code, and find out the hard way that a certain machine on the\nfactory floor needs a supervisor present before you touch it. Every new hire repeats the same\nquestions, and some of them make the same mistakes, because nobody wrote the rules down."}),"\n",(0,o.jsx)(n.p,{children:"At the second company, day one starts with an employee handbook. It does not tell them how to do\ntheir actual job \u2014 that still takes training and practice. But it tells them the rules of the\nworkplace: which tools to use, who signs off on purchases, and which actions are simply not\nallowed, no matter how convenient they seem in the moment. The new hire still has to think and\nwork \u2014 the handbook just means they are not guessing at the basics."}),"\n",(0,o.jsxs)(n.p,{children:["A coding agent starts every task the way that first new hire started their day: with no memory of\nyour last conversation, and no idea what your project's rules are, unless a file tells it. A\n",(0,o.jsx)(n.strong,{children:"coding-agent harness"})," is that handbook \u2014 a set of plain text files, added to your project once,\nthat any coding agent reads before it touches a single line of code."]}),"\n",(0,o.jsx)(n.h2,{id:"2-the-five-things-a-harness-needs",children:"2. The five things a harness needs"}),"\n",(0,o.jsx)(n.p,{children:"A working harness answers five questions. Miss one, and the agent has to guess \u2014 and a guess is\nexactly what a spec, and now a harness, exists to remove."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"1. Project context."})," A file (usually named ",(0,o.jsx)(n.code,{children:"CLAUDE.md"})," or ",(0,o.jsx)(n.code,{children:"AGENTS.md"}),", more on that below) that\nstates, in plain words: what this project does, what its main folders are for, and the handful of\nconventions that matter. For the PlatformOps Toolkit you have been building, that means: this is a\nTyper-based command-line tool, written in Python 3.12, managed with ",(0,o.jsx)(n.code,{children:"uv"}),"; the real code lives in\n",(0,o.jsx)(n.code,{children:"src/platformops/"}),", the tests live in ",(0,o.jsx)(n.code,{children:"tests/"}),", and the helper scripts live in ",(0,o.jsx)(n.code,{children:"scripts/"}),". An agent\nthat knows this does not have to spend its first few minutes exploring the folder structure and\nguessing which file matters \u2014 it already knows."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"2. Approved commands."}),' The exact commands the agent should run, spelled out \u2014 not "run the\ntests" but ',(0,o.jsx)(n.code,{children:"uv run pytest"}),". Without this, an agent might run plain ",(0,o.jsx)(n.code,{children:"pytest"}),", skip the virtual\nenvironment ",(0,o.jsx)(n.code,{children:"uv"})," manages, and hit an import error that has nothing to do with your code. A short,\nexact list \u2014 the test command, the lint command, the format command, the type checker, the command\nthat runs the CLI itself \u2014 removes that guesswork entirely."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"3. Safety rules."})," A short list of things the agent must never do, no matter how reasonable they\nlook in the middle of a task: never delete ",(0,o.jsx)(n.code,{children:"uv.lock"})," (it pins the exact versions your project\ndepends on), never add a dependency without asking you first, never run a command that deletes a\nwhole directory. These are not suggestions. An agent that hits a failing dependency resolution\nmight genuinely believe deleting the lock file and starting fresh is the fastest fix \u2014 the safety\nrule is what stops it from acting on that belief on its own."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"4. A verification script."}),' One command the agent runs itself, before it tells you a task is\ndone. This is the harness\'s answer to a problem you already saw in Module 14: an agent can say\n"tests pass" without having actually run anything. A verification script \u2014 one file, one command,\nthat runs the tests, the linter, and the type checker in sequence and stops at the first failure \u2014\nturns that claim into something you, or the agent, can actually check.']}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"5. Definition of done."}),' A short checklist that decides whether a task is really finished: tests\npass, the linter is clean, types check, and \u2014 for this project \u2014 the changelog has a new entry. A\n"definition of done" written as a checklist is something you can verify against the diff. "I think\nthis is ready" is not.']}),"\n",(0,o.jsx)(n.admonition,{title:"Why the harness names commands and files exactly",type:"tip",children:(0,o.jsxs)(n.p,{children:['Vague instructions produce vague compliance. "Follow good testing practices" leaves an agent free\nto interpret what "good" means. "',(0,o.jsx)(n.code,{children:"uv run pytest -q"})," must exit 0\" leaves nothing to interpret. The\nharness works because it is specific, the same way a spec's acceptance criteria work because they\nare specific."]})}),"\n",(0,o.jsx)(n.h2,{id:"3-portability--one-set-of-rules-several-file-names",children:"3. Portability \u2014 one set of rules, several file names"}),"\n",(0,o.jsx)(n.p,{children:"Here is the part that surprises people the first time they see it: you write the harness content\nonce, and it works with more than one coding agent, almost unchanged."}),"\n",(0,o.jsx)(n.p,{children:"Think of a safety poster printed in three languages and pinned up in three branches of the same\ncompany. The words on the page differ by branch, but the actual rule behind them \u2014 wear the safety\ngear, report the leak, do not prop the fire door open \u2014 is identical everywhere. Nobody rewrites\nthe safety policy three times; they translate the same policy onto three posters."}),"\n",(0,o.jsxs)(n.p,{children:["Coding agents work the same way. Claude Code looks for a file named ",(0,o.jsx)(n.code,{children:"CLAUDE.md"})," at the root of\nyour project. Codex CLI looks for ",(0,o.jsx)(n.code,{children:"AGENTS.md"}),". Both are just markdown files sitting in your\nrepository \u2014 plain text, no special format, nothing an agent-specific tool has to generate. That\nmeans the five sections above \u2014 project context, approved commands, safety rules, the verify\nscript, the definition of done \u2014 can live in one file, and you save (or copy) it under whichever\nfilename the agent you are using expects. You are not writing different instructions for each\ntool. You are writing one set of project rules and labeling the door differently for each visitor."]}),"\n",(0,o.jsx)(n.mermaid,{value:'flowchart LR\n    A["Agent starts\\na task"] --\x3e B["Reads the harness\\n(CLAUDE.md / AGENTS.md)"]\n    B --\x3e C["Uses only the\\napproved commands"]\n    C --\x3e D["Follows the\\nsafety rules"]\n    D --\x3e E["Runs the\\nverify script"]\n    E --\x3e F{"Definition of\\ndone met?"}\n    F --\x3e|"no"| C\n    F --\x3e|"yes"| G["Reports the\\ntask as done"]'}),"\n",(0,o.jsx)(n.p,{children:"Nothing about this flow depends on which agent is running it. The harness sets the rules; the\nagent's job is to follow them, the same way any new hire follows the handbook regardless of which\ndepartment they work in."}),"\n",(0,o.jsx)(n.h2,{id:"common-pitfalls",children:"Common pitfalls"}),"\n",(0,o.jsx)(n.admonition,{title:"Common pitfalls",type:"tip",children:(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"A harness that is too vague to change anything."}),' "Write clean, maintainable code" is not a\nrule an agent can check itself against \u2014 it is a wish. Every line in the harness should be\nsomething you could point to in a diff and say "this line did, or did not, follow that."']}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"An approved-commands list that has drifted from reality."})," If your project switches its lint\ncommand, or adds a new gate script, and the harness still names the old one, the agent will\nfollow the harness correctly \u2014 and still do the wrong thing, because the harness itself is\nwrong. The harness is only as good as its last update."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Safety rules nobody actually enforces."}),' A rule that says "never add a dependency without\napproval" is not a safety rule if you rubber-stamp every diff that adds one anyway. The review\ndiscipline from Module 14 still applies here \u2014 the harness states the rule, your review is what\nmakes it real.']}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:'No verification script, so "done" is just a claim again.'})," This is the exact verification gap\nfrom Module 14, reintroduced through the back door. A harness without a command the agent can\nrun to check its own work is a handbook with no way to prove anyone read it."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Writing the harness once and never touching it again."})," Your project changes \u2014 a new script, a\nnew safety concern, a new command. The harness has to change with it, or it slowly starts giving\nan agent instructions that no longer match the project it is working in."]}),"\n"]})})]})}function c(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>r});var s=t(6540);let o={},a=s.createContext(o);function i(e){let n=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),s.createElement(a.Provider,{value:n},e.children)}}}]);